[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Fitness Tracker User Health &amp; Activity Analytics Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a73e8;
    --primary-dark: #0d47a1;
    --accent: #34a853;
    --accent2: #fbbc04;
    --accent3: #ea4335;
    --accent4: #9c27b0;
    --bg: #f8f9fa;
    --card: #ffffff;
    --text: #202124;
    --text-muted: #5f6368;
    --border: #e8eaed;
    --shadow: 0 1px 3px rgba(0,0,0,0.12), 0 1px 2px rgba(0,0,0,0.08);
    --shadow-md: 0 4px 6px rgba(0,0,0,0.1), 0 2px 4px rgba(0,0,0,0.06);
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--bg);
    color: var(--text);
    font-size: 14px;
    line-height: 1.6;
  }

  /* HEADER */
  .report-header {
    background: linear-gradient(135deg, #0d47a1 0%, #1565c0 40%, #1a73e8 100%);
    color: white;
    padding: 48px 48px 40px;
    position: relative;
    overflow: hidden;
  }
  .report-header::after {
    content: '';
    position: absolute;
    right: -60px;
    top: -60px;
    width: 300px;
    height: 300px;
    background: rgba(255,255,255,0.05);
    border-radius: 50%;
  }
  .report-header::before {
    content: '';
    position: absolute;
    right: 100px;
    bottom: -80px;
    width: 200px;
    height: 200px;
    background: rgba(255,255,255,0.04);
    border-radius: 50%;
  }
  .report-header .label {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    opacity: 0.8;
    margin-bottom: 10px;
  }
  .report-header h1 {
    font-size: 30px;
    font-weight: 700;
    margin-bottom: 12px;
    line-height: 1.2;
    position: relative;
  }
  .report-header .subtitle {
    font-size: 15px;
    opacity: 0.85;
    max-width: 620px;
    position: relative;
  }
  .report-header .meta {
    margin-top: 24px;
    display: flex;
    gap: 32px;
    font-size: 12px;
    opacity: 0.75;
    position: relative;
  }
  .report-header .meta span { font-weight: 600; opacity: 1; }

  /* NAVIGATION */
  .toc {
    background: white;
    border-bottom: 2px solid var(--border);
    padding: 0 48px;
    display: flex;
    gap: 0;
    overflow-x: auto;
  }
  .toc a {
    display: block;
    padding: 14px 18px;
    font-size: 12.5px;
    font-weight: 500;
    color: var(--text-muted);
    text-decoration: none;
    border-bottom: 3px solid transparent;
    white-space: nowrap;
    transition: all 0.2s;
  }
  .toc a:hover { color: var(--primary); border-bottom-color: var(--primary); }

  /* MAIN CONTENT */
  .container { max-width: 1280px; margin: 0 auto; padding: 40px 48px; }

  /* KPI STRIP */
  .kpi-strip {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 40px;
  }
  .kpi-card {
    background: var(--card);
    border-radius: 10px;
    padding: 20px;
    box-shadow: var(--shadow);
    border-top: 4px solid var(--primary);
    position: relative;
  }
  .kpi-card:nth-child(2) { border-top-color: var(--accent); }
  .kpi-card:nth-child(3) { border-top-color: var(--accent2); }
  .kpi-card:nth-child(4) { border-top-color: var(--accent3); }
  .kpi-card:nth-child(5) { border-top-color: var(--accent4); }
  .kpi-card .kpi-label {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 6px;
  }
  .kpi-card .kpi-value {
    font-size: 28px;
    font-weight: 700;
    color: var(--text);
    line-height: 1;
    margin-bottom: 4px;
  }
  .kpi-card .kpi-sub {
    font-size: 11.5px;
    color: var(--text-muted);
  }

  /* SECTIONS */
  .section {
    margin-bottom: 48px;
  }
  .section-header {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 24px;
    padding-bottom: 12px;
    border-bottom: 2px solid var(--border);
  }
  .section-number {
    background: var(--primary);
    color: white;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    font-weight: 700;
    flex-shrink: 0;
  }
  .section-header h2 {
    font-size: 20px;
    font-weight: 700;
    color: var(--text);
  }
  .section-header .section-desc {
    font-size: 13px;
    color: var(--text-muted);
    margin-top: 2px;
  }

  /* CARDS */
  .card {
    background: var(--card);
    border-radius: 10px;
    padding: 24px;
    box-shadow: var(--shadow);
    margin-bottom: 20px;
  }
  .card h3 {
    font-size: 14px;
    font-weight: 600;
    color: var(--text);
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .card h3 .badge {
    font-size: 10px;
    background: #e8f0fe;
    color: var(--primary);
    padding: 2px 8px;
    border-radius: 12px;
    font-weight: 600;
  }
  .card h3 .badge-green { background: #e6f4ea; color: #1e8e3e; }
  .card h3 .badge-orange { background: #fef3e2; color: #e37400; }
  .card h3 .badge-red { background: #fce8e6; color: #c5221f; }

  /* GRID LAYOUTS */
  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  .grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }
  .grid-2-1 { display: grid; grid-template-columns: 2fr 1fr; gap: 20px; }
  .grid-1-2 { display: grid; grid-template-columns: 1fr 2fr; gap: 20px; }

  /* CHART CONTAINERS */
  .chart-wrap {
    position: relative;
    height: 280px;
  }
  .chart-wrap-sm {
    position: relative;
    height: 220px;
  }
  .chart-wrap-lg {
    position: relative;
    height: 340px;
  }
  .chart-wrap-xl {
    position: relative;
    height: 380px;
  }

  /* STAT TABLES */
  .stat-table { width: 100%; border-collapse: collapse; }
  .stat-table th {
    text-align: left;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    padding: 8px 10px;
    border-bottom: 2px solid var(--border);
  }
  .stat-table td {
    padding: 9px 10px;
    font-size: 13px;
    border-bottom: 1px solid var(--border);
    color: var(--text);
  }
  .stat-table tr:last-child td { border-bottom: none; }
  .stat-table tr:hover td { background: #f8f9fa; }
  .stat-table .num { font-weight: 600; color: var(--primary); text-align: right; }
  .stat-table .num-accent { font-weight: 600; color: var(--accent); text-align: right; }

  /* BAR MINI */
  .bar-mini {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 10px;
  }
  .bar-mini .bar-label { font-size: 12.5px; width: 100px; flex-shrink: 0; }
  .bar-mini .bar-track { flex: 1; background: #e8eaed; border-radius: 4px; height: 10px; }
  .bar-mini .bar-fill { height: 10px; border-radius: 4px; background: var(--primary); transition: width 0.3s; }
  .bar-mini .bar-val { font-size: 12px; font-weight: 600; width: 60px; text-align: right; flex-shrink: 0; }

  /* INSIGHT BOXES */
  .insight-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 24px; }
  .insight-box {
    background: white;
    border-radius: 10px;
    padding: 20px;
    box-shadow: var(--shadow);
    border-left: 5px solid var(--primary);
  }
  .insight-box:nth-child(2) { border-left-color: var(--accent); }
  .insight-box:nth-child(3) { border-left-color: var(--accent2); }
  .insight-box:nth-child(4) { border-left-color: var(--accent3); }
  .insight-box:nth-child(5) { border-left-color: var(--accent4); }
  .insight-box:nth-child(6) { border-left-color: #00bcd4; }
  .insight-box .insight-num {
    font-size: 28px;
    font-weight: 800;
    color: var(--primary);
    line-height: 1;
    margin-bottom: 6px;
  }
  .insight-box:nth-child(2) .insight-num { color: var(--accent); }
  .insight-box:nth-child(3) .insight-num { color: #e37400; }
  .insight-box:nth-child(4) .insight-num { color: var(--accent3); }
  .insight-box:nth-child(5) .insight-num { color: var(--accent4); }
  .insight-box:nth-child(6) .insight-num { color: #00bcd4; }
  .insight-box .insight-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }
  .insight-box .insight-desc { font-size: 12.5px; color: var(--text); line-height: 1.5; }

  /* RECOMMENDATION CARDS */
  .rec-card {
    background: white;
    border-radius: 10px;
    padding: 20px 24px;
    box-shadow: var(--shadow);
    margin-bottom: 14px;
    display: flex;
    gap: 18px;
    align-items: flex-start;
  }
  .rec-icon {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    background: #e8f0fe;
    color: var(--primary);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
    flex-shrink: 0;
  }
  .rec-icon.green { background: #e6f4ea; }
  .rec-icon.orange { background: #fef3e2; }
  .rec-icon.purple { background: #f3e5f5; }
  .rec-icon.red { background: #fce8e6; }
  .rec-icon.teal { background: #e0f2f1; }
  .rec-body h4 { font-size: 14px; font-weight: 700; color: var(--text); margin-bottom: 4px; }
  .rec-body p { font-size: 13px; color: var(--text-muted); line-height: 1.55; }
  .rec-body .rec-tag {
    display: inline-block;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    background: #e8f0fe;
    color: var(--primary);
    padding: 2px 8px;
    border-radius: 12px;
    margin-bottom: 6px;
  }
  .rec-body .rec-tag.green { background: #e6f4ea; color: #1e8e3e; }
  .rec-body .rec-tag.orange { background: #fef3e2; color: #e37400; }
  .rec-body .rec-tag.purple { background: #f3e5f5; color: #7b1fa2; }
  .rec-body .rec-tag.red { background: #fce8e6; color: #c5221f; }

  /* BADGE ROW */
  .badge-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
  .badge-pill {
    font-size: 12px;
    font-weight: 500;
    padding: 4px 12px;
    border-radius: 16px;
    background: #e8f0fe;
    color: var(--primary);
  }

  /* HEATMAP */
  .heatmap-table { width: 100%; border-collapse: collapse; font-size: 11px; }
  .heatmap-table th {
    padding: 5px 4px;
    font-size: 10px;
    font-weight: 600;
    color: var(--text-muted);
    text-align: center;
  }
  .heatmap-table td {
    padding: 4px;
    text-align: center;
    border-radius: 3px;
    font-size: 11px;
    font-weight: 500;
  }
  .heatmap-table .row-label {
    font-weight: 600;
    color: var(--text-muted);
    text-align: left;
    padding-left: 6px;
  }

  /* DIVIDER */
  .divider { border: none; border-top: 1px solid var(--border); margin: 32px 0; }

  /* FOOTER */
  .report-footer {
    background: #1a1a2e;
    color: rgba(255,255,255,0.6);
    padding: 24px 48px;
    font-size: 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 48px;
  }
  .report-footer strong { color: rgba(255,255,255,0.9); }

  /* DATA NOTE */
  .data-note {
    background: #e8f4fd;
    border-left: 4px solid var(--primary);
    border-radius: 0 6px 6px 0;
    padding: 10px 16px;
    font-size: 12.5px;
    color: #1557b0;
    margin-bottom: 20px;
  }

  /* RESPONSIVE */
  @media (max-width: 900px) {
    .kpi-strip { grid-template-columns: repeat(3, 1fr); }
    .grid-2, .grid-3, .grid-2-1, .grid-1-2 { grid-template-columns: 1fr; }
    .insight-grid { grid-template-columns: 1fr 1fr; }
    .container { padding: 24px 20px; }
    .report-header { padding: 32px 20px; }
  }
  @media (max-width: 600px) {
    .kpi-strip { grid-template-columns: 1fr 1fr; }
    .insight-grid { grid-template-columns: 1fr; }
  }

  .text-right { text-align: right; }
  .mt-16 { margin-top: 16px; }
  .mb-0 { margin-bottom: 0; }
</style>
</head>
<body>

<!-- ============ HEADER ============ -->
<div class="report-header">
  <div class="label">Health Analytics Report</div>
  <h1>Fitness Tracker User Health &amp; Activity Analytics</h1>
  <div class="subtitle">A comprehensive analysis of daily health metrics, activity patterns, and lifestyle indicators across a synthetic cohort of fitness tracker users, 2015–2025.</div>
  <div class="meta">
    Prepared for: <span>Health Analytics Team</span>
    &nbsp;|&nbsp; Dataset: <span>4,000 records · 970 unique users</span>
    &nbsp;|&nbsp; Period: <span>Jan 2015 – Dec 2025</span>
    &nbsp;|&nbsp; Report Date: <span>April 21, 2026</span>
  </div>
</div>

<!-- ============ TOC ============ -->
<div class="toc">
  <a href="#kpis">KPI Summary</a>
  <a href="#demographics">Demographics</a>
  <a href="#activity">Activity &amp; Workouts</a>
  <a href="#vitals">Vitals &amp; Sleep</a>
  <a href="#lifestyle">Lifestyle &amp; Wellness</a>
  <a href="#temporal">Temporal Trends ★</a>
  <a href="#insights">Key Insights</a>
</div>

<div class="container">

  <!-- ============ KPI STRIP ============ -->
  <div id="kpis" style="padding-top:8px;">
    <div class="kpi-strip">
      <div class="kpi-card">
        <div class="kpi-label">Avg Daily Steps</div>
        <div class="kpi-value">10,574</div>
        <div class="kpi-sub">Cohort-wide mean · 4,000 records</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Workout Participation</div>
        <div class="kpi-value">83.1%</div>
        <div class="kpi-sub">Days with logged workout activity</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Avg Calories Burned</div>
        <div class="kpi-value">616.7</div>
        <div class="kpi-sub">kcal/day · SD ±211</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Avg Sleep Duration</div>
        <div class="kpi-value">6.99 h</div>
        <div class="kpi-sub">Per day across all users</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Avg Stress Level</div>
        <div class="kpi-value">5.45</div>
        <div class="kpi-sub">Self-reported · scale 1–10</div>
      </div>
    </div>
  </div>

  <!-- ============ SECTION 1: DEMOGRAPHICS ============ -->
  <div id="demographics" class="section">
    <div class="section-header">
      <div class="section-number">1</div>
      <div>
        <h2>User Demographics &amp; Body Metrics Overview</h2>
        <div class="section-desc">Distribution of age, gender, height, weight, and BMI across the 970-user cohort</div>
      </div>
    </div>

    <div class="grid-2">
      <!-- Gender & Age Distribution -->
      <div class="card">
        <h3>Gender Split <span class="badge">n=4,000 records</span></h3>
        <div class="chart-wrap-sm">
          <canvas id="genderChart"></canvas>
        </div>
      </div>

      <div class="card">
        <h3>Age Group Distribution</h3>
        <div class="chart-wrap-sm">
          <canvas id="ageChart"></canvas>
        </div>
      </div>
    </div>

