function stepsToColor(v) {
  const min = 8000, max = 13500;
  const t = Math.max(0, Math.min(1, (v - min) / (max - min)));
  const r = Math.round(255 * (1-t) + 26 * t);
  const g = Math.round(255 * (1-t) + 115 * t);
  const b = Math.round(255 * (1-t) + 232 * t);
  return `rgb(${r},${g},${b})`;
}

