  td0.textContent = year;
  tr.appendChild(td0);
  heatmapData[year].forEach(v => {
    const td = document.createElement('td');
    td.style.background = stepsToColor(v);
    td.style.color = v > 11500 ? '#fff' : '#202124';
    td.textContent = (v/1000).toFixed(1) + 'K';
    tr.appendChild(td);
  });
  tbody.appendChild(tr);
});

